// pkgFUM: carries the follow-up reply and the first reply back to "Panel Cure Normalize 1", which joins them and asks nothing more (fum_done).
return $input.all().map((it,i)=>{let p=null;try{p=$('FUM Needed? Panel 1').itemMatching(i).json;}catch(e){p=null;}if(!p){try{p=$('FUM Needed? Panel 1').all()[i].json;}catch(e){p=null;}}
 return {json:{fum_done:true,fum_asked:p&&p.fum?p.fum.asked:[],fum_items:p&&p.fum?p.fum.items:[],fum_others:p&&p.fum?(p.fum.others||[]):[],fum_first:p&&p.fum?p.fum.first:null,fum_call:it.json},pairedItem:{item:i}};});

